SELECT COUNT(*)
FROM LINE_DAILY_BATCH_TARGET
WHERE usage_date = #{usageDate}

SELECT COALESCE(MAX(line_id), 0)
FROM LINE_DAILY_BATCH_TARGET
WHERE usage_date = #{usageDate}

SELECT line_id
FROM LINE
WHERE deleted_at IS NULL
  AND line_id > #{lastLineId}
ORDER BY line_id
LIMIT #{limit}

mapper.update:
UPDATE LINE_DAILY_BATCH_TARGET SET status = 'PROCESSING', status_updated_at = CURRENT_TIMESTAMP(6), worker_id = #{workerId} WHERE id IN
#{id}
AND status IN ('PENDING', 'RETRYABLE', 'PROCESSING')

UPDATE LINE_DAILY_BATCH_TARGET
SET status = #{status},
    status_updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{id}
  AND status = 'PROCESSING'
  AND worker_id = #{workerId}

UPDATE LINE_DAILY_BATCH_TARGET
SET status = 'RETRYABLE',
    status_updated_at = CURRENT_TIMESTAMP(6),
    worker_id = NULL,
    retry_count = retry_count + 1,
    last_error_code = #{lastErrorCode},
    last_error_message = #{lastErrorMessage}
WHERE id = #{id}
  AND status = 'PROCESSING'
  AND worker_id = #{workerId}
  AND retry_count < #{maxRetryCount}

UPDATE LINE_DAILY_BATCH_TARGET
SET status = 'FAILED',
    status_updated_at = CURRENT_TIMESTAMP(6),
    last_error_code = #{lastErrorCode},
    last_error_message = #{lastErrorMessage}
WHERE id = #{id}
  AND status = 'PROCESSING'
  AND worker_id = #{workerId}
